-- ── 2. Helpers (the browser generators' identities and arithmetic, exactly) ─────────────────────────────────────────
-- slug(label) = the first ten hex characters of SHA-256 over the UTF-8 label (financialGeneration/common.ts).
CREATE OR REPLACE FUNCTION public._fs_slug(p_text text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, public AS $$
  SELECT left(encode(sha256(convert_to(p_text, 'UTF8')), 'hex'), 10);
$$;
-- One trimmed cell of an evidence row by column name ('' when the column is absent) — columnReader().
CREATE OR REPLACE FUNCTION public._fs_ev_cell(p_doc jsonb, p_row jsonb, p_col text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, public AS $$
  SELECT btrim(coalesce(p_row ->> (SELECT (c.o - 1)::integer FROM jsonb_array_elements_text(p_doc -> 'columns') WITH ORDINALITY c(v, o) WHERE c.v = p_col LIMIT 1), ''));
$$;
-- A validated plain decimal string in exact minor units at the batch's scale (moneyFromDecimalString); NULL for a blank.
CREATE OR REPLACE FUNCTION public._fs_ev_minor(p_text text, p_scale integer)
RETURNS numeric LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, public AS $$
  SELECT CASE WHEN p_text IS NULL OR btrim(p_text) = '' THEN NULL ELSE round(btrim(p_text)::numeric * power(10::numeric, p_scale), 0) END;
$$;
-- The one usable batch of a family and role for the period: the latest version of each series, usable when VALID or
-- VALID_WITH_WARNINGS and stated in the statements' currency and scale (a batch without amounts carries neither). Two
-- usable series is ambiguous, never a choice.
CREATE OR REPLACE FUNCTION public._fs_ev_pick(p_company_id uuid, p_period_year integer, p_type text, p_role text, p_currency text, p_scale integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_n integer;
  v_b record;
BEGIN
  SELECT count(*) INTO v_n FROM (
    SELECT DISTINCT ON (b.series_key) b.validation_status FROM public.financial_evidence_batches b
     WHERE b.company_id = p_company_id AND b.reporting_period_id = 'FY' || p_period_year::text AND b.evidence_type = p_type AND b.period_role = p_role
     ORDER BY b.series_key, b.version DESC) l
   WHERE l.validation_status IN ('VALID', 'VALID_WITH_WARNINGS');
  IF v_n = 0 THEN RETURN jsonb_build_object('present', false, 'usable', false); END IF;
  SELECT l.* INTO v_b FROM (
    SELECT DISTINCT ON (b.series_key) b.evidence_batch_id, b.validation_status, b.currency, b.scale, b.batch_document FROM public.financial_evidence_batches b
     WHERE b.company_id = p_company_id AND b.reporting_period_id = 'FY' || p_period_year::text AND b.evidence_type = p_type AND b.period_role = p_role
     ORDER BY b.series_key, b.version DESC) l
   WHERE l.validation_status IN ('VALID', 'VALID_WITH_WARNINGS') ORDER BY l.evidence_batch_id LIMIT 1;
  IF v_n > 1 THEN
    RETURN jsonb_build_object('present', true, 'usable', false, 'batchId', v_b.evidence_batch_id, 'blocker', 'EVIDENCE_SERIES_AMBIGUOUS:' || p_type || ':' || p_role);
  END IF;
  IF v_b.currency IS NOT NULL AND v_b.scale IS NOT NULL AND (v_b.currency IS DISTINCT FROM p_currency OR v_b.scale IS DISTINCT FROM p_scale) THEN
    RETURN jsonb_build_object('present', true, 'usable', false, 'batchId', v_b.evidence_batch_id, 'blocker', 'EVIDENCE_DENOMINATION_MISMATCH:' || p_type || ':' || p_role);
  END IF;
  RETURN jsonb_build_object('present', true, 'usable', true, 'batchId', v_b.evidence_batch_id, 'doc', v_b.batch_document);
END;
$$;

-- ── 3. The evidence statements, composed by the database ────────────────────────────────────────────────────────────
-- VOLATILE: reads the composition (a transaction-local working table) and uses working tables of its own; writes
-- nothing persistent. Unreadable workspaces get the composition's own 'unavailable' answer, never figures.
CREATE OR REPLACE FUNCTION public.fs_evidence_statements(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_comp jsonb;
  v_input jsonb;
  v_currency text;
  v_scale integer;
  v_has_cmp boolean;
  v_periods text[];
  v_eq_pids text[];
  v_pid text;
  v_ck text;
  v_role text;
  v_pick jsonb;
  v_ledger_doc jsonb;
  v_map jsonb;
  v_prior jsonb;
  v_prior_used boolean := false;
  v_blockers text[] := '{}';
  v_batches jsonb := '[]'::jsonb;
  v_statements jsonb := '{}'::jsonb;
  v_reasons text[] := '{}';
  v_skipped text[] := '{}';
  v_established text[] := '{}';
  v_cfexpected jsonb := '{}'::jsonb;
  v_opening jsonb := '{}'::jsonb;
  v_closing jsonb := '{}'::jsonb;
  v_missing text[];
  v_k text;
  v_a numeric; v_r numeric; v_e numeric; v_o numeric; v_x numeric;
  v_amt numeric; v_amt2 numeric; v_cand numeric; v_cast numeric;
  v_n integer; v_have integer;
  v_body jsonb;
  v_figures jsonb;
  r record;
  c_assets CONSTANT text[] := ARRAY['BANK_ACCOUNT', 'CASH_ON_HAND', 'MOBILE_MONEY', 'DESIGNATED_PROJECT', 'RESTRICTED_CASH'];
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  v_comp := public.fs_statement_composition(p_company_id, p_period_year);
  IF v_comp ->> 'state' IS DISTINCT FROM 'composed' THEN
    RETURN jsonb_build_object('state', coalesce(v_comp ->> 'state', 'unavailable'), 'reason', v_comp ->> 'reason');
  END IF;
  v_input := public.fs_reporting_input(p_company_id, p_period_year);
  IF v_input ->> 'state' IS DISTINCT FROM 'current' THEN
    RETURN jsonb_build_object('state', 'unavailable', 'reason', 'reporting input ' || coalesce(v_input ->> 'state', 'unknown'));
  END IF;
  v_currency := v_comp -> 'current' ->> 'currency';
  v_scale := (v_comp -> 'current' ->> 'exponent')::integer;
  v_has_cmp := v_comp -> 'comparative' ->> 'state' = 'available';
  v_periods := CASE WHEN v_has_cmp THEN ARRAY['CURRENT', 'COMPARATIVE_1'] ELSE ARRAY['CURRENT'] END;

  CREATE TEMP TABLE IF NOT EXISTS fs_ev_fig (fact_id text PRIMARY KEY, amount numeric NOT NULL) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_cf (pid text, activity text, label text, amount numeric) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_eq (pid text, component text, mtype text, description text, amount numeric) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_map (account_key text, category text, effect text, include boolean, rn integer) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_lin (pid text, account_key text, amount numeric) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_scope (pid text, account_key text, is_cash boolean, zero boolean) ON COMMIT DROP;
  CREATE TEMP TABLE IF NOT EXISTS fs_ev_code (code text, amount numeric) ON COMMIT DROP;
  DELETE FROM pg_temp.fs_ev_fig; DELETE FROM pg_temp.fs_ev_cf; DELETE FROM pg_temp.fs_ev_eq; DELETE FROM pg_temp.fs_ev_map;
  DELETE FROM pg_temp.fs_ev_lin; DELETE FROM pg_temp.fs_ev_scope; DELETE FROM pg_temp.fs_ev_code;

  -- The statement of financial position's account figures per period (the browser's line:detail:sfp:<account> facts).
  INSERT INTO pg_temp.fs_ev_lin
  SELECT CASE x ->> 'period' WHEN 'current' THEN 'CURRENT' ELSE 'COMPARATIVE_1' END, x ->> 'accountKey', (x ->> 'amountMinor')::numeric
    FROM jsonb_array_elements(v_comp -> 'lines') l CROSS JOIN LATERAL jsonb_array_elements(l -> 'lineage') x
   WHERE l ->> 'statement' = 'SFP' AND x ->> 'kind' = 'account' AND (x ->> 'period' = 'current' OR v_has_cmp);
  -- Each period's own accounts from its authoritative reporting input, with the reviewed cash flag (DEFECT D-3).
  INSERT INTO pg_temp.fs_ev_scope
  SELECT 'CURRENT', a ->> 'accountKey', (a ->> 'isCashAccount')::boolean, (a ->> 'debitMinor')::numeric - (a ->> 'creditMinor')::numeric = 0
    FROM jsonb_array_elements(coalesce(v_input -> 'current' -> 'accounts', '[]'::jsonb)) a;
  IF v_has_cmp THEN
    INSERT INTO pg_temp.fs_ev_scope
    SELECT 'COMPARATIVE_1', a ->> 'accountKey', (a ->> 'isCashAccount')::boolean, (a ->> 'debitMinor')::numeric - (a ->> 'creditMinor')::numeric = 0
      FROM jsonb_array_elements(coalesce(v_input -> 'comparative' -> 'accounts', '[]'::jsonb)) a;
  END IF;

  -- ── Evidence per period: the ledger and the equity movements ──
  FOREACH v_pid IN ARRAY v_periods LOOP
    v_role := CASE v_pid WHEN 'CURRENT' THEN 'CURRENT' ELSE 'COMPARATIVE' END;
    v_pick := public._fs_ev_pick(p_company_id, p_period_year, 'TRANSACTION_LEDGER', v_role, v_currency, v_scale);
    IF coalesce((v_pick ->> 'present')::boolean, false) AND NOT coalesce((v_pick ->> 'usable')::boolean, false) THEN v_blockers := v_blockers || (v_pick ->> 'blocker'); END IF;
    IF coalesce((v_pick ->> 'usable')::boolean, false) THEN
      IF v_pid = 'CURRENT' THEN v_ledger_doc := v_pick -> 'doc'; END IF;
      v_batches := v_batches || jsonb_build_object('type', 'TRANSACTION_LEDGER', 'role', v_role, 'batchId', v_pick ->> 'batchId');
      INSERT INTO pg_temp.fs_ev_cf
      SELECT v_pid, public._fs_ev_cell(d.doc, x, 'activity'), public._fs_ev_cell(d.doc, x, 'cash_flow_line'),
             CASE WHEN public._fs_ev_cell(d.doc, x, 'receipt') <> '' THEN public._fs_ev_minor(public._fs_ev_cell(d.doc, x, 'receipt'), v_scale)
                  ELSE -public._fs_ev_minor(public._fs_ev_cell(d.doc, x, 'payment'), v_scale) END
        FROM (SELECT v_pick -> 'doc' AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') x;
      -- A batch whose rows cannot be read as the family's columns (not the shape the intake writes) yields no figure.
      IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf c WHERE c.pid = v_pid AND (c.amount IS NULL OR c.activity = '' OR c.label = '')) THEN
        DELETE FROM pg_temp.fs_ev_cf WHERE pid = v_pid;
        IF v_pid = 'CURRENT' THEN v_ledger_doc := NULL; END IF;
        v_blockers := v_blockers || ('EVIDENCE_ROWS_UNREADABLE:TRANSACTION_LEDGER:' || v_role);
      END IF;
    END IF;
    v_pick := public._fs_ev_pick(p_company_id, p_period_year, 'EQUITY_MOVEMENTS', v_role, v_currency, v_scale);
    IF coalesce((v_pick ->> 'present')::boolean, false) AND NOT coalesce((v_pick ->> 'usable')::boolean, false) THEN v_blockers := v_blockers || (v_pick ->> 'blocker'); END IF;
    IF coalesce((v_pick ->> 'usable')::boolean, false) THEN
      v_batches := v_batches || jsonb_build_object('type', 'EQUITY_MOVEMENTS', 'role', v_role, 'batchId', v_pick ->> 'batchId');
      INSERT INTO pg_temp.fs_ev_eq
      SELECT v_pid, public._fs_ev_cell(d.doc, x, 'component'), public._fs_ev_cell(d.doc, x, 'movement_type'), public._fs_ev_cell(d.doc, x, 'description'),
             public._fs_ev_minor(public._fs_ev_cell(d.doc, x, 'amount'), v_scale)
        FROM (SELECT v_pick -> 'doc' AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') x;
      IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_eq e WHERE e.pid = v_pid AND (e.amount IS NULL OR e.component = '' OR e.mtype = '')) THEN
        DELETE FROM pg_temp.fs_ev_eq WHERE pid = v_pid;
        v_blockers := v_blockers || ('EVIDENCE_ROWS_UNREADABLE:EQUITY_MOVEMENTS:' || v_role);
      END IF;
    END IF;
  END LOOP;
  v_map := public._fs_ev_pick(p_company_id, p_period_year, 'CASH_ACCOUNT_MAP', 'CURRENT', v_currency, v_scale);
  IF coalesce((v_map ->> 'present')::boolean, false) AND NOT coalesce((v_map ->> 'usable')::boolean, false) THEN v_blockers := v_blockers || (v_map ->> 'blocker'); END IF;
  v_prior := public._fs_ev_pick(p_company_id, p_period_year, 'PRIOR_PERIOD_STATEMENTS', 'COMPARATIVE', v_currency, v_scale);
  IF coalesce((v_prior ->> 'present')::boolean, false) AND NOT coalesce((v_prior ->> 'usable')::boolean, false) THEN v_blockers := v_blockers || (v_prior ->> 'blocker'); END IF;
  -- Without a current-period ledger or equity batch there is no statement at all (the generators report a gap).
  IF NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf WHERE pid = 'CURRENT') THEN DELETE FROM pg_temp.fs_ev_cf; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_eq WHERE pid = 'CURRENT') THEN DELETE FROM pg_temp.fs_ev_eq; END IF;

  -- ── Cash flows: lines, activity subtotals, net movement ──
  IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf) THEN
    INSERT INTO pg_temp.fs_ev_fig
    SELECT 'fact:line:cf:' || lower(c.activity) || ':' || public._fs_slug(c.label) || ':' || c.pid, sum(c.amount) FROM pg_temp.fs_ev_cf c GROUP BY c.pid, c.activity, c.label;
    -- An activity's net is presented for a period only when every presented line of that activity has a figure for it.
    INSERT INTO pg_temp.fs_ev_fig
    SELECT 'fact:line:cf:' || lower(g.activity) || ':net:' || g.pid, g.total
      FROM (SELECT c.pid, c.activity, sum(c.amount) AS total, count(DISTINCT c.label) AS n FROM pg_temp.fs_ev_cf c GROUP BY c.pid, c.activity) g
     WHERE g.n = (SELECT count(DISTINCT u.label) FROM pg_temp.fs_ev_cf u WHERE u.activity = g.activity);
    INSERT INTO pg_temp.fs_ev_fig
    SELECT 'fact:line:cf:net-increase:' || s.pid, s.total
      FROM (SELECT substring(f.fact_id FROM ':([^:]+)$') AS pid, sum(f.amount) AS total, count(*) AS n FROM pg_temp.fs_ev_fig f WHERE f.fact_id ~ '^fact:line:cf:[a-z]+:net:' GROUP BY 1) s
     WHERE s.n = (SELECT count(DISTINCT c.activity) FROM pg_temp.fs_ev_cf c);
  END IF;
  v_statements := v_statements || jsonb_build_object('STATEMENT_OF_CASH_FLOWS', CASE WHEN EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf) THEN 'composed' ELSE 'not_composed' END);

  -- ── The cash perimeter (CASH_ACCOUNT_MAP + the statement of financial position), per period ──
  IF coalesce((v_map ->> 'usable')::boolean, false) THEN
    v_batches := v_batches || jsonb_build_object('type', 'CASH_ACCOUNT_MAP', 'role', 'CURRENT', 'batchId', v_map ->> 'batchId');
    INSERT INTO pg_temp.fs_ev_map
    SELECT public._fs_ev_cell(d.doc, x, 'account_key'), public._fs_ev_cell(d.doc, x, 'category'), public._fs_ev_cell(d.doc, x, 'effect'),
           upper(public._fs_ev_cell(d.doc, x, 'include_in_cash_flow')) LIKE 'Y%', o::integer
      FROM (SELECT v_map -> 'doc' AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') WITH ORDINALITY t(x, o);
    IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_map m WHERE m.account_key = '' OR m.category = '' OR m.effect = '') THEN
      DELETE FROM pg_temp.fs_ev_map;
      v_reasons := v_reasons || 'EVIDENCE_ROWS_UNREADABLE:CASH_ACCOUNT_MAP:CURRENT'::text;
    END IF;
    -- Every account reviewed as cash in a period must be in the map: the current period refuses, a comparative is skipped.
    FOREACH v_pid IN ARRAY v_periods LOOP
      SELECT array_agg(s.account_key ORDER BY s.account_key) INTO v_missing FROM pg_temp.fs_ev_scope s
       WHERE s.pid = v_pid AND s.is_cash IS TRUE AND NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_map m WHERE m.account_key = s.account_key);
      IF v_missing IS NOT NULL THEN
        IF v_pid = 'CURRENT' THEN
          FOREACH v_k IN ARRAY v_missing LOOP v_reasons := v_reasons || ('CASH_ACCOUNT_UNMAPPED:' || v_k); END LOOP;
        ELSE
          v_skipped := v_skipped || v_pid;
        END IF;
      END IF;
    END LOOP;
    -- Every mapped account is in a presented period's trial balance; one with a balance is on the statement.
    FOR r IN SELECT m.account_key FROM pg_temp.fs_ev_map m ORDER BY m.rn LOOP
      IF NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_scope s WHERE s.account_key = r.account_key)
         OR (NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_lin l WHERE l.account_key = r.account_key)
             AND EXISTS (SELECT 1 FROM pg_temp.fs_ev_scope s WHERE s.account_key = r.account_key AND NOT s.zero)) THEN
        v_reasons := v_reasons || ('CASH_ACCOUNT_NOT_IN_TRIAL_BALANCE:' || r.account_key);
      END IF;
    END LOOP;
    IF v_reasons = '{}' THEN
      FOREACH v_pid IN ARRAY v_periods LOOP
        CONTINUE WHEN v_pid = ANY (v_skipped);
        SELECT array_agg(m.account_key ORDER BY m.account_key) INTO v_missing
          FROM pg_temp.fs_ev_map m JOIN pg_temp.fs_ev_scope s ON s.pid = v_pid AND s.account_key = m.account_key
         WHERE NOT s.zero AND NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_lin l WHERE l.pid = v_pid AND l.account_key = m.account_key);
        IF v_missing IS NOT NULL THEN
          IF v_pid = 'CURRENT' THEN v_reasons := v_reasons || ('CASH_PERIMETER_BALANCE_MISSING:' || array_to_string(v_missing, ',')); END IF;
          CONTINUE;
        END IF;
        -- A contribution is the account's statement figure (zero when the period holds it at nil), added or subtracted as mapped.
        SELECT coalesce(sum(t.v) FILTER (WHERE t.category = ANY (c_assets)), 0),
               coalesce(sum(t.v) FILTER (WHERE t.category IN ('RESTRICTED_CASH', 'DESIGNATED_PROJECT')), 0),
               coalesce(sum(t.v) FILTER (WHERE t.category = 'CASH_ECL_ALLOWANCE'), 0),
               coalesce(sum(t.v) FILTER (WHERE t.category = 'OVERDRAFT' AND t.include), 0),
               coalesce(sum(t.v) FILTER (WHERE t.category = 'EXCLUDED_NON_CASH'), 0)
          INTO v_a, v_r, v_e, v_o, v_x
          FROM (SELECT m.category, m.include,
                       CASE WHEN m.effect = 'ADD' THEN 1 ELSE -1 END * coalesce((SELECT l.amount FROM pg_temp.fs_ev_lin l WHERE l.pid = v_pid AND l.account_key = m.account_key LIMIT 1), 0) AS v
                  FROM pg_temp.fs_ev_map m JOIN pg_temp.fs_ev_scope s ON s.pid = v_pid AND s.account_key = m.account_key) t;
        INSERT INTO pg_temp.fs_ev_fig VALUES
          ('fact:cashperim:gross:' || v_pid, v_a), ('fact:cashperim:restricted:' || v_pid, v_r), ('fact:cashperim:ecl:' || v_pid, v_e),
          ('fact:cashperim:overdraft:' || v_pid, v_o), ('fact:cashperim:excluded:' || v_pid, v_x),
          ('fact:cashperim:cfexpected:' || v_pid, v_a + v_o), ('fact:cashperim:net:' || v_pid, v_a + v_e);
        v_cfexpected := v_cfexpected || jsonb_build_object(v_pid, (v_a + v_o)::text);
        v_established := v_established || v_pid;
      END LOOP;
      IF NOT ('CURRENT' = ANY (v_established)) AND v_reasons = '{}' THEN v_reasons := v_reasons || 'CASH_PERIMETER_NOT_ESTABLISHED'::text; END IF;
    END IF;
    IF v_reasons <> '{}' THEN
      -- Not established: no perimeter figure at all, every reason a blocker (the generator produces no figure either).
      DELETE FROM pg_temp.fs_ev_fig WHERE fact_id LIKE 'fact:cashperim:%';
      v_cfexpected := '{}'::jsonb; v_established := '{}';
      v_blockers := v_blockers || v_reasons;
    END IF;

    -- ── Ledger completeness, account by account (cashLedgerAuthority.ts) ──
    IF v_ledger_doc IS NOT NULL THEN
      INSERT INTO pg_temp.fs_ev_code
      SELECT public._fs_ev_cell(d.doc, x, 'cash_account_code'),
             sum(CASE WHEN public._fs_ev_cell(d.doc, x, 'receipt') <> '' THEN public._fs_ev_minor(public._fs_ev_cell(d.doc, x, 'receipt'), v_scale)
                      ELSE -public._fs_ev_minor(public._fs_ev_cell(d.doc, x, 'payment'), v_scale) END)
        FROM (SELECT v_ledger_doc AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') x GROUP BY 1;
      FOR r IN SELECT c.code, c.amount FROM pg_temp.fs_ev_code c
                WHERE NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_map m WHERE m.account_key = c.code AND (m.category = ANY (c_assets) OR (m.category = 'OVERDRAFT' AND m.include)))
                ORDER BY c.code LOOP
        INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:cashroll:orphan:' || public._fs_slug(r.code), r.amount);
        v_blockers := v_blockers || ('CASHFLOW_LEDGER_ACCOUNT_NOT_CASH:' || r.code);
      END LOOP;
      FOR r IN SELECT m.account_key, m.effect FROM pg_temp.fs_ev_map m
                WHERE m.category = ANY (c_assets) OR (m.category = 'OVERDRAFT' AND m.include) ORDER BY m.account_key LOOP
        v_amt := coalesce((SELECT c.amount FROM pg_temp.fs_ev_code c WHERE c.code = r.account_key), 0);
        INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:cashroll:ledger:' || public._fs_slug(r.account_key), v_amt);
        SELECT l.amount INTO v_cand FROM pg_temp.fs_ev_lin l WHERE l.pid = 'CURRENT' AND l.account_key = r.account_key LIMIT 1;
        SELECT l.amount INTO v_amt2 FROM pg_temp.fs_ev_lin l WHERE l.pid = 'COMPARATIVE_1' AND l.account_key = r.account_key LIMIT 1;
        IF v_cand IS NULL OR v_amt2 IS NULL THEN
          v_blockers := v_blockers || ('CASHFLOW_ROLLFORWARD_BALANCE_MISSING:' || r.account_key);
        ELSE
          IF r.effect <> 'ADD' THEN v_cand := -v_cand; v_amt2 := -v_amt2; END IF;
          INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:cashroll:tb:' || public._fs_slug(r.account_key), v_cand - v_amt2);
          IF v_amt <> v_cand - v_amt2 THEN v_blockers := v_blockers || ('CASHFLOW_ACCOUNT_ROLLFORWARD:' || r.account_key || ':' || (v_amt - (v_cand - v_amt2))::text); END IF;
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ── Cash flows: opening and closing cash, and the ties ──
  IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf) THEN
    FOREACH v_pid IN ARRAY v_periods LOOP
      CONTINUE WHEN NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_cf c WHERE c.pid = v_pid);
      v_cand := NULL; v_amt := NULL; v_amt2 := NULL;
      IF v_pid = 'CURRENT' THEN
        -- Every authority that speaks about opening cash: the comparative period's perimeter and the signed prior
        -- statement of financial position's cash line. Two that disagree choose nothing.
        IF v_cfexpected ? 'COMPARATIVE_1' THEN v_amt := (v_cfexpected ->> 'COMPARATIVE_1')::numeric; END IF;
        IF coalesce((v_prior ->> 'usable')::boolean, false) THEN
          SELECT public._fs_ev_minor(public._fs_ev_cell(d.doc, t.x, 'amount'), v_scale) INTO v_amt2
            FROM (SELECT v_prior -> 'doc' AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') WITH ORDINALITY t(x, o)
           WHERE public._fs_ev_cell(d.doc, t.x, 'statement_type') = 'FINANCIAL_POSITION' AND public._fs_ev_cell(d.doc, t.x, 'line_key') = 'cash_and_cash_equivalents_sfp'
           ORDER BY t.o LIMIT 1;
        END IF;
        IF v_amt IS NOT NULL AND v_amt2 IS NOT NULL AND v_amt <> v_amt2 THEN
          v_blockers := v_blockers || 'CASHFLOW_OPENING_CASH_CONFLICT'::text;
        ELSE
          v_cand := coalesce(v_amt, v_amt2);
          IF v_amt IS NULL AND v_amt2 IS NOT NULL THEN v_prior_used := true; END IF;
        END IF;
      ELSIF coalesce((v_prior ->> 'usable')::boolean, false) THEN
        -- The comparative period's opening cash: only the signed prior-year statement of cash flows states it.
        SELECT public._fs_ev_minor(public._fs_ev_cell(d.doc, t.x, 'amount'), v_scale) INTO v_cand
          FROM (SELECT v_prior -> 'doc' AS doc) d CROSS JOIN LATERAL jsonb_array_elements(d.doc -> 'rows') WITH ORDINALITY t(x, o)
         WHERE public._fs_ev_cell(d.doc, t.x, 'statement_type') = 'CASH_FLOWS' AND public._fs_ev_cell(d.doc, t.x, 'line_key') = 'cash_and_cash_equivalents_opening_cf'
         ORDER BY t.o LIMIT 1;
        IF v_cand IS NOT NULL THEN v_prior_used := true; END IF;
      END IF;
      IF v_cand IS NOT NULL THEN
        INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:cf:opening:' || v_pid, v_cand);
        v_opening := v_opening || jsonb_build_object(v_pid, v_cand::text);
        SELECT f.amount INTO v_amt FROM pg_temp.fs_ev_fig f WHERE f.fact_id = 'fact:line:cf:net-increase:' || v_pid;
        IF v_amt IS NOT NULL THEN
          INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:cf:closing:' || v_pid, v_cand + v_amt);
          v_closing := v_closing || jsonb_build_object(v_pid, (v_cand + v_amt)::text);
        END IF;
      END IF;
    END LOOP;
    IF v_prior_used THEN v_batches := v_batches || jsonb_build_object('type', 'PRIOR_PERIOD_STATEMENTS', 'role', 'COMPARATIVE', 'batchId', v_prior ->> 'batchId'); END IF;
    FOREACH v_pid IN ARRAY v_periods LOOP
      IF (v_closing ? v_pid) AND (v_cfexpected ? v_pid) AND (v_closing ->> v_pid)::numeric <> (v_cfexpected ->> v_pid)::numeric THEN
        v_blockers := v_blockers || ('CASHFLOW_CLOSING_CASH_TIE:' || v_pid || ':' || ((v_closing ->> v_pid)::numeric - (v_cfexpected ->> v_pid)::numeric)::text);
      END IF;
    END LOOP;
    IF (v_opening ? 'CURRENT') AND (v_closing ? 'COMPARATIVE_1') AND (v_opening ->> 'CURRENT')::numeric <> (v_closing ->> 'COMPARATIVE_1')::numeric THEN
      v_blockers := v_blockers || ('CASHFLOW_OPENING_NOT_PRIOR_CLOSING:' || ((v_opening ->> 'CURRENT')::numeric - (v_closing ->> 'COMPARATIVE_1')::numeric)::text);
    END IF;
  END IF;

  -- ── Changes in equity (equityStatement.ts) ──
  IF EXISTS (SELECT 1 FROM pg_temp.fs_ev_eq) THEN
    SELECT array_agg(DISTINCT e.pid ORDER BY e.pid) INTO v_eq_pids FROM pg_temp.fs_ev_eq e;
    SELECT array_agg(k ORDER BY k) INTO v_missing FROM (
      SELECT c.component || ' (' || p.pid || ')' AS k FROM (SELECT DISTINCT e.component FROM pg_temp.fs_ev_eq e) c CROSS JOIN unnest(v_eq_pids) p(pid)
       WHERE NOT EXISTS (SELECT 1 FROM pg_temp.fs_ev_eq e WHERE e.component = c.component AND e.pid = p.pid AND e.mtype = 'OPENING_BALANCE')) x;
    IF v_missing IS NOT NULL THEN
      -- Opening equity is never inferred: no statement (the generator reports a gap).
      v_blockers := v_blockers || ('SOCIE_OPENING_MISSING:' || array_to_string(v_missing, ';'));
      DELETE FROM pg_temp.fs_ev_eq;
    ELSE
      INSERT INTO pg_temp.fs_ev_fig
      SELECT 'fact:line:eq:' || public._fs_slug(e.component) || ':opening:' || e.pid, e.amount FROM pg_temp.fs_ev_eq e WHERE e.mtype = 'OPENING_BALANCE';
      INSERT INTO pg_temp.fs_ev_fig
      SELECT 'fact:line:eq:' || public._fs_slug(e.component) || ':' || lower(e.mtype) || ':' || public._fs_slug(e.description) || ':' || e.pid, sum(e.amount)
        FROM pg_temp.fs_ev_eq e WHERE e.mtype NOT IN ('OPENING_BALANCE', 'CLOSING_BALANCE') GROUP BY e.component, e.mtype, e.description, e.pid;
      -- Closing: as stated in the evidence (tested against opening + movements), else computed when every movement line
      -- of the component (across the periods) has a figure for the period.
      FOR r IN SELECT DISTINCT e.component FROM pg_temp.fs_ev_eq e LOOP
        FOREACH v_pid IN ARRAY v_eq_pids LOOP
          SELECT e.amount INTO v_amt FROM pg_temp.fs_ev_eq e WHERE e.component = r.component AND e.pid = v_pid AND e.mtype = 'CLOSING_BALANCE' LIMIT 1;
          SELECT count(*) FILTER (WHERE x.v IS NULL), coalesce(sum(x.v), 0) INTO v_n, v_amt2 FROM (
            SELECT (SELECT sum(e.amount) FROM pg_temp.fs_ev_eq e WHERE e.component = r.component AND e.pid = v_pid AND e.mtype = k.mtype AND e.description = k.description) AS v
              FROM (SELECT DISTINCT e.mtype, e.description FROM pg_temp.fs_ev_eq e WHERE e.component = r.component AND e.mtype NOT IN ('OPENING_BALANCE', 'CLOSING_BALANCE')) k) x;
          v_cast := CASE WHEN v_n = 0 THEN (SELECT f.amount FROM pg_temp.fs_ev_fig f WHERE f.fact_id = 'fact:line:eq:' || public._fs_slug(r.component) || ':opening:' || v_pid) + v_amt2 END;
          IF v_amt IS NOT NULL THEN
            INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:eq:' || public._fs_slug(r.component) || ':closing:' || v_pid, v_amt);
            IF v_cast IS NOT NULL AND v_cast <> v_amt THEN
              v_blockers := v_blockers || ('SOCIE_COMPONENT_DOES_NOT_CAST:' || r.component || ':' || v_pid || ':' || (v_amt - v_cast)::text);
            END IF;
          ELSIF v_cast IS NOT NULL THEN
            INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:eq:' || public._fs_slug(r.component) || ':closing:' || v_pid, v_cast);
          END IF;
        END LOOP;
      END LOOP;
      FOREACH v_pid IN ARRAY v_eq_pids LOOP
        v_ck := CASE v_pid WHEN 'CURRENT' THEN 'current' ELSE 'comparative' END;
        INSERT INTO pg_temp.fs_ev_fig
        SELECT 'fact:line:eq:total-opening:' || v_pid, sum(f.amount) FROM pg_temp.fs_ev_fig f WHERE f.fact_id ~ ('^fact:line:eq:[0-9a-f]{10}:opening:' || v_pid || '$') HAVING count(*) > 0;
        -- The result recognised in equity: every PROFIT_OR_LOSS line (across the periods) has a figure for the period.
        SELECT count(*), count(f.amount), sum(f.amount) INTO v_n, v_have, v_amt
          FROM (SELECT DISTINCT e.component, e.description FROM pg_temp.fs_ev_eq e WHERE e.mtype = 'PROFIT_OR_LOSS') k
          LEFT JOIN pg_temp.fs_ev_fig f ON f.fact_id = 'fact:line:eq:' || public._fs_slug(k.component) || ':profit_or_loss:' || public._fs_slug(k.description) || ':' || v_pid;
        IF v_n > 0 AND v_have = v_n THEN
          INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:eq:total-profit:' || v_pid, v_amt);
          IF v_comp -> 'totals' -> v_ck ->> 'state' = 'complete' AND v_amt <> (v_comp -> 'totals' -> v_ck ->> 'profitOrLossMinor')::numeric THEN
            v_blockers := v_blockers || ('SOCIE_PROFIT_TIE:' || v_pid || ':' || (v_amt - (v_comp -> 'totals' -> v_ck ->> 'profitOrLossMinor')::numeric)::text);
          END IF;
        END IF;
        SELECT count(*), count(f.amount), sum(f.amount) INTO v_n, v_have, v_amt
          FROM (SELECT DISTINCT e.component FROM pg_temp.fs_ev_eq e) c
          LEFT JOIN pg_temp.fs_ev_fig f ON f.fact_id = 'fact:line:eq:' || public._fs_slug(c.component) || ':closing:' || v_pid;
        IF v_n > 0 AND v_have = v_n THEN
          INSERT INTO pg_temp.fs_ev_fig VALUES ('fact:line:eq:total-closing:' || v_pid, v_amt);
          IF v_comp -> 'totals' -> v_ck ->> 'state' = 'complete' AND v_amt <> (v_comp -> 'totals' -> v_ck ->> 'totalEquityMinor')::numeric THEN
            v_blockers := v_blockers || ('SOCIE_CLOSING_EQUITY_TIE:' || v_pid || ':' || (v_amt - (v_comp -> 'totals' -> v_ck ->> 'totalEquityMinor')::numeric)::text);
          END IF;
        END IF;
      END LOOP;
      IF 'COMPARATIVE_1' = ANY (v_eq_pids) THEN
        FOR r IN SELECT c.component, o.amount AS op, cl.amount AS clo FROM (SELECT DISTINCT e.component FROM pg_temp.fs_ev_eq e) c
                  JOIN pg_temp.fs_ev_fig o ON o.fact_id = 'fact:line:eq:' || public._fs_slug(c.component) || ':opening:CURRENT'
                  LEFT JOIN pg_temp.fs_ev_fig cl ON cl.fact_id = 'fact:line:eq:' || public._fs_slug(c.component) || ':closing:COMPARATIVE_1'
                 ORDER BY c.component LOOP
          IF r.clo IS NOT NULL AND r.op <> r.clo THEN v_blockers := v_blockers || ('SOCIE_OPENING_NOT_PRIOR_CLOSING:' || r.component || ':' || (r.op - r.clo)::text); END IF;
        END LOOP;
      END IF;
    END IF;
  END IF;
  v_statements := v_statements || jsonb_build_object('STATEMENT_OF_CHANGES_IN_EQUITY', CASE WHEN EXISTS (SELECT 1 FROM pg_temp.fs_ev_eq) THEN 'composed' ELSE 'not_composed' END);

  SELECT coalesce(jsonb_agg(jsonb_build_object('factId', f.fact_id, 'amountMinor', f.amount::text) ORDER BY f.fact_id), '[]'::jsonb) INTO v_figures FROM pg_temp.fs_ev_fig f;
  v_body := jsonb_build_object('contract', 'fs-evidence-statements/1', 'periodYear', p_period_year, 'currency', v_currency, 'scale', v_scale,
    'periods', to_jsonb(v_periods), 'statements', v_statements, 'evidenceBatches', v_batches,
    'cashPerimeter', jsonb_build_object('established', to_jsonb(v_established), 'cfExpectedMinor', v_cfexpected),
    'cashFlow', jsonb_build_object('openingMinor', v_opening, 'closingMinor', v_closing),
    'figures', v_figures, 'blockers', to_jsonb(v_blockers));
  RETURN jsonb_build_object('state', 'composed') || v_body || jsonb_build_object('statementsSha256', encode(sha256(convert_to(v_body::text, 'UTF8')), 'hex'));
END;
$$;

-- ── 4. Applicability decisions: data-decided requirements cannot be decided by hand ─────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_decide_requirement(p_company_id uuid, p_period_year integer, p_requirement_id text, p_decision text,
  p_reason text, p_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_refusal text;
  v_prior record;
  v_latest text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '28000'; END IF;
  IF p_company_id IS NULL OR p_period_year IS NULL OR p_requirement_id IS NULL OR p_request_id IS NULL OR p_decision NOT IN ('applicable', 'not_applicable')
     OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 3 AND 2000 THEN RETURN jsonb_build_object('outcome', 'invalid_request'); END IF;
  v_refusal := public._fs_notes_refusal(p_company_id, v_uid);
  IF v_refusal IS NOT NULL THEN RETURN jsonb_build_object('outcome', v_refusal); END IF;
  -- Only a CONDITIONAL disclosure the data cannot decide (the early-application disclosure follows the edition decision;
  -- income tax and revenue follow the composed statement — 20261111100000), or one of the three comprehensive-income
  -- line items whose presence the trial balance cannot show (20261022100000).
  IF NOT EXISTS (SELECT 1 FROM public.fs_pack_requirements r WHERE r.pack_family = 'ifrs-for-smes' AND r.requirement_id = p_requirement_id
                   AND ((r.kind = 'DISCLOSURE' AND r.applicability = 'CONDITIONAL' AND r.requirement_id NOT IN ('smes.note.early_application', 'smes.note.income_tax', 'smes.note.revenue'))
                        OR r.requirement_id IN ('smes.sci.5_5_e', 'smes.sci.5_5_g', 'smes.sci.5_5_h'))) THEN
    RETURN jsonb_build_object('outcome', 'not_decidable');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('fs_notes:' || p_company_id::text || ':' || p_period_year::text, 0));
  SELECT * INTO v_prior FROM public.fs_requirement_decisions d WHERE d.actor_user_id = v_uid AND d.request_id = p_request_id;
  IF FOUND THEN
    IF v_prior.company_id = p_company_id AND v_prior.period_year = p_period_year AND v_prior.requirement_id = p_requirement_id
       AND v_prior.decision = p_decision AND v_prior.reason = btrim(p_reason) THEN RETURN jsonb_build_object('outcome', 'recorded', 'replay', true, 'decisionId', v_prior.id); END IF;
    RETURN jsonb_build_object('outcome', 'request_reused');
  END IF;
  SELECT d.decision INTO v_latest FROM public.fs_requirement_decisions d
   WHERE d.company_id = p_company_id AND d.period_year = p_period_year AND d.requirement_id = p_requirement_id ORDER BY d.seq DESC LIMIT 1;
  IF v_latest = p_decision THEN RETURN jsonb_build_object('outcome', 'unchanged'); END IF;
  INSERT INTO public.fs_requirement_decisions (company_id, period_year, requirement_id, decision, reason, actor_user_id, firm_member_id, request_id)
  VALUES (p_company_id, p_period_year, p_requirement_id, p_decision, btrim(p_reason), v_uid, public._cr_member(p_company_id, v_uid), p_request_id)
  RETURNING jsonb_build_object('outcome', 'recorded', 'decisionId', id) INTO v_latest;
  RETURN v_latest::jsonb;
END;
$$;

-- ── 5. Notes status v3: the data-decided disclosures ────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_notes_status(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_comp jsonb;
  v_early boolean;
  v_cmp_on boolean;
  v_start date;
  v_end date;
  v_reqs jsonb := '[]'::jsonb;
  v_blockers text[] := '{}';
  v_body jsonb;
  r record;
  v_status text;
  v_detail jsonb;
  v_dec record;
  v_txt record;
  v_sub record;
  v_def record;
  v_cur numeric;
  v_cmp numeric;
  v_comp_ok boolean;
  v_ci jsonb;
  v_line text;
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  v_comp := public.fs_statement_composition(p_company_id, p_period_year);
  IF v_comp ->> 'state' IS DISTINCT FROM 'composed' THEN RETURN v_comp; END IF;
  v_early := (v_comp -> 'pack' ->> 'earlyApplication')::boolean;
  v_cmp_on := v_comp -> 'comparative' ->> 'state' = 'available';
  v_start := (v_comp -> 'current' ->> 'reportingStart')::date;
  v_end := (v_comp -> 'current' ->> 'reportingEnd')::date;
  v_comp_ok := v_comp -> 'totals' -> 'current' ->> 'state' = 'complete' AND jsonb_array_length(v_comp -> 'blockers') = 0;

  FOR r IN SELECT * FROM public.fs_pack_requirements p WHERE p.pack_family = 'ifrs-for-smes' AND p.kind IN ('STATEMENT', 'DISCLOSURE', 'PERIOD', 'SCHEDULE') ORDER BY p.sort_order LOOP
    v_status := NULL; v_detail := '{}'::jsonb;
    SELECT t.id, t.body, t.source_ref, t.seq INTO v_txt FROM public.fs_disclosure_texts t
     WHERE t.company_id = p_company_id AND t.period_year = p_period_year AND t.requirement_id = r.requirement_id ORDER BY t.seq DESC LIMIT 1;
    IF r.kind = 'DISCLOSURE' THEN
      IF r.requirement_id = 'smes.note.early_application' AND NOT v_early THEN
        v_status := 'not_applicable'; v_detail := jsonb_build_object('basis', 'The edition is applied from its effective date.');
      ELSIF r.requirement_id IN ('smes.note.income_tax', 'smes.note.revenue') THEN
        -- [20261111100000] Decided by the data: the disclosure applies when the composed line carries an amount at either date.
        v_line := CASE r.requirement_id WHEN 'smes.note.income_tax' THEN 'sci.tax_expense' ELSE 'sci.revenue' END;
        SELECT coalesce(sum(abs((l -> 'current' ->> 'amountMinor')::numeric)), 0) + coalesce(sum(abs((l -> 'comparative' ->> 'amountMinor')::numeric)), 0) INTO v_cur
          FROM jsonb_array_elements(v_comp -> 'lines') l WHERE l ->> 'lineId' = v_line;
        IF v_cur = 0 THEN
          v_status := 'not_applicable'; v_detail := jsonb_build_object('basis', 'The composed line ' || v_line || ' carries no amount at either reporting date.');
        ELSE
          v_detail := jsonb_build_object('basis', 'The composed line ' || v_line || ' carries an amount; the disclosure applies.');
        END IF;
      ELSIF r.applicability = 'CONDITIONAL' AND r.requirement_id <> 'smes.note.early_application' THEN
        SELECT d.id, d.decision, d.reason INTO v_dec FROM public.fs_requirement_decisions d
         WHERE d.company_id = p_company_id AND d.period_year = p_period_year AND d.requirement_id = r.requirement_id ORDER BY d.seq DESC LIMIT 1;
        IF NOT FOUND THEN v_status := 'undecided';
        ELSIF v_dec.decision = 'not_applicable' THEN v_status := 'not_applicable'; v_detail := jsonb_build_object('basis', v_dec.reason, 'decisionId', v_dec.id);
        END IF;
        IF v_status IS NULL THEN v_detail := jsonb_build_object('decisionId', v_dec.id); END IF;
      END IF;
      IF v_status IS NULL THEN
        IF v_txt.body IS NOT NULL THEN v_status := 'provided'; v_detail := v_detail || jsonb_build_object('textId', v_txt.id, 'sourceRef', v_txt.source_ref);
        ELSE v_status := 'missing'; END IF;
      END IF;
      IF r.blocking AND v_status = 'missing' THEN v_blockers := v_blockers || ('REQUIRED_DISCLOSURE_MISSING:' || r.requirement_id); END IF;
      IF r.blocking AND v_status = 'undecided' THEN v_blockers := v_blockers || ('REQUIREMENT_UNDECIDED:' || r.requirement_id); END IF;
    ELSIF r.kind = 'PERIOD' THEN
      IF v_start IS NULL OR v_end IS NULL THEN v_status := 'dates_unknown'; v_blockers := v_blockers || 'PERIOD_DATES_UNKNOWN'::text;
      ELSIF v_end = (v_start + interval '1 year' - interval '1 day')::date THEN v_status := 'satisfied'; v_detail := jsonb_build_object('basis', 'A twelve-month period.');
      ELSIF v_txt.body IS NOT NULL THEN v_status := 'provided'; v_detail := jsonb_build_object('textId', v_txt.id, 'basis', 'A period longer or shorter than one year, disclosed.');
      ELSE v_status := 'missing'; v_detail := jsonb_build_object('basis', 'A period longer or shorter than one year needs its disclosure.');
        v_blockers := v_blockers || 'NON_ANNUAL_PERIOD_DISCLOSURE_MISSING'::text;
      END IF;
    ELSIF r.kind = 'SCHEDULE' THEN
      SELECT * INTO v_def FROM public.fs_schedule_definitions d WHERE d.pack_family = 'ifrs-for-smes' AND d.requirement_id = r.requirement_id;
      SELECT coalesce(sum((l -> 'current' ->> 'amountMinor')::numeric), 0), CASE WHEN v_cmp_on THEN coalesce(sum((l -> 'comparative' ->> 'amountMinor')::numeric), 0) END
        INTO v_cur, v_cmp FROM jsonb_array_elements(v_comp -> 'lines') l WHERE l ->> 'lineId' = ANY (v_def.line_ids);
      IF v_cur = 0 AND coalesce(v_cmp, 0) = 0 THEN
        v_status := 'not_applicable'; v_detail := jsonb_build_object('basis', 'No carrying amount on the composed statement at either date.');
      ELSE
        SELECT s.id, s.opening_total, s.closing_total, s.content_sha256, s.source_ref INTO v_sub FROM public.fs_schedule_submissions s
         WHERE s.company_id = p_company_id AND s.period_year = p_period_year AND s.schedule_id = v_def.schedule_id ORDER BY s.seq DESC LIMIT 1;
        v_detail := jsonb_build_object('scheduleId', v_def.schedule_id, 'composedClosingMinor', v_cur::text, 'composedOpeningMinor', v_cmp::text);
        IF NOT FOUND THEN v_status := 'missing'; v_blockers := v_blockers || ('SCHEDULE_MISSING:' || v_def.schedule_id);
        ELSE
          v_detail := v_detail || jsonb_build_object('submissionId', v_sub.id, 'contentSha256', v_sub.content_sha256, 'sourceRef', v_sub.source_ref,
                                                     'scheduleOpeningMinor', v_sub.opening_total::text, 'scheduleClosingMinor', v_sub.closing_total::text);
          IF v_sub.closing_total <> v_cur THEN
            v_status := 'closing_mismatch'; v_detail := v_detail || jsonb_build_object('differenceMinor', (v_sub.closing_total - v_cur)::text);
            v_blockers := v_blockers || ('SCHEDULE_CLOSING_MISMATCH:' || v_def.schedule_id);
          ELSIF v_cmp IS NULL THEN
            v_status := 'reconciled_opening_unverified'; v_detail := v_detail || jsonb_build_object('basis', 'No authoritative prior-year statement to agree the opening amount to.');
          ELSIF v_sub.opening_total <> v_cmp THEN
            v_status := 'opening_mismatch'; v_detail := v_detail || jsonb_build_object('differenceMinor', (v_sub.opening_total - v_cmp)::text);
            v_blockers := v_blockers || ('SCHEDULE_OPENING_MISMATCH:' || v_def.schedule_id);
          ELSE v_status := 'reconciled';
          END IF;
        END IF;
      END IF;
    ELSE -- STATEMENT
      IF r.requirement_id IN ('smes.set.sfp', 'smes.set.sci') THEN
        v_status := CASE WHEN v_comp_ok THEN 'composed' ELSE 'incomplete' END;
        IF NOT v_comp_ok THEN v_blockers := v_blockers || ('STATEMENT_INCOMPLETE:' || r.requirement_id); END IF;
      ELSIF r.requirement_id = 'smes.set.socie' THEN
        IF public._fs_evidence_present(p_company_id, p_period_year, 'EQUITY_MOVEMENTS') THEN v_status := 'evidence_present';
          v_detail := jsonb_build_object('basis', 'Equity-movement evidence is held; the statement is generated from it, never from a trial balance.');
        ELSE v_status := 'evidence_missing'; v_blockers := v_blockers || 'STATEMENT_EVIDENCE_MISSING:smes.set.socie'::text; END IF;
      ELSIF r.requirement_id = 'smes.set.scf' THEN
        IF public._fs_evidence_present(p_company_id, p_period_year, 'TRANSACTION_LEDGER') AND public._fs_evidence_present(p_company_id, p_period_year, 'CASH_ACCOUNT_MAP') THEN
          v_status := 'evidence_present';
          v_detail := jsonb_build_object('basis', 'A cash transaction ledger and cash account map are held; the statement is generated from them and reconciled account by account, never from a trial balance.');
        ELSE v_status := 'evidence_missing'; v_blockers := v_blockers || 'STATEMENT_EVIDENCE_MISSING:smes.set.scf'::text; END IF;
      ELSE
        v_status := 'derived'; -- the notes: complete when their components are (each blocks on its own)
      END IF;
    END IF;
    v_reqs := v_reqs || jsonb_build_array(jsonb_build_object('requirementId', r.requirement_id, 'kind', r.kind, 'blocking', r.blocking, 'status', v_status) || v_detail);
  END LOOP;

  -- Comprehensive income (5.5(e), (g), (h), (i)): decided, composed or explicitly unsupported (20261022100000).
  v_ci := public._fs_comprehensive_income(p_company_id, p_period_year, v_comp);
  v_reqs := v_reqs || (v_ci -> 'requirements');
  v_blockers := v_blockers || ARRAY(SELECT jsonb_array_elements_text(v_ci -> 'blockers'));

  v_body := jsonb_build_object('contract', 'fs-notes-status/3', 'packId', v_comp -> 'pack' ->> 'packId', 'compositionSha256', v_comp ->> 'compositionSha256',
                               'periodYear', p_period_year, 'requirements', v_reqs, 'blockers', to_jsonb(v_blockers));
  RETURN jsonb_build_object('state', 'evaluated') || v_body || jsonb_build_object('statusSha256', encode(sha256(convert_to(v_body::text, 'UTF8')), 'hex'));
END;
$$;

-- ── 5b. Roll-forward: the comparative, as reported, against the prior year's issued FINAL version ──────────────────
-- VOLATILE because it reads the composition (a transaction-local working table); writes nothing persistent.
CREATE OR REPLACE FUNCTION public.fs_prior_final_reconciliation(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_comp jsonb;
  v_prior record;
  v_diffs jsonb;
  v_blockers text[] := '{}';
  v_body jsonb;
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  v_comp := public.fs_statement_composition(p_company_id, p_period_year);
  IF v_comp ->> 'state' IS DISTINCT FROM 'composed' THEN RETURN jsonb_build_object('state', coalesce(v_comp ->> 'state', 'unavailable'), 'reason', v_comp ->> 'reason'); END IF;
  -- The prior year's latest issued version: the FINAL publication with the highest sequence for this company and that period.
  SELECT r.report_id, r.report_version, r.report_document, encode(sha256(convert_to(r.report_document::text, 'UTF8')), 'hex') AS doc_sha, p.created_at
    INTO v_prior
    FROM public.financial_statement_publications p
    JOIN public.financial_statement_reports r ON r.report_id = p.report_id AND r.report_version = p.report_version
   WHERE p.company_id = p_company_id AND r.company_id = p_company_id AND r.period_year = p_period_year - 1 AND p.state = 'FINAL'
     AND r.provenance_origin = 'TRIAL_BALANCE_DERIVED' AND r.report_document #>> '{framework,kind}' = 'IFRS_FOR_SMES'
   ORDER BY p.seq DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('state', 'no_prior_final', 'periodYear', p_period_year, 'priorPeriodYear', p_period_year - 1);
  END IF;
  IF v_comp -> 'comparative' ->> 'state' IS DISTINCT FROM 'available' OR (v_comp -> 'comparative' ->> 'periodYear')::integer IS DISTINCT FROM p_period_year - 1 THEN
    RETURN jsonb_build_object('state', 'comparative_unavailable', 'periodYear', p_period_year,
      'priorFinal', jsonb_build_object('reportId', v_prior.report_id, 'reportVersion', v_prior.report_version, 'documentSha256', v_prior.doc_sha, 'issuedAt', v_prior.created_at));
  END IF;
  -- Every composed comparative line AS REPORTED against the figure issued for that line (fact:current:<section>:<lineId> in
  -- the prior FINAL document); a line present on only one side is a difference too. Accounts, totals and restatement facts
  -- are not lines and are not compared here (totals follow their lines).
  SELECT coalesce(jsonb_agg(d ORDER BY d ->> 'factId'), '[]'::jsonb) INTO v_diffs FROM (
    SELECT jsonb_build_object('factId', coalesce(c.fid, f.fid), 'issuedMinor', f.issued, 'comparativeAsReportedMinor', c.rep,
             'differenceMinor', CASE WHEN c.rep IS NOT NULL AND f.issued IS NOT NULL THEN (c.rep::numeric - f.issued::numeric)::text END) AS d
      FROM (SELECT 'fact:comparative:' || (l ->> 'section') || ':' || (l ->> 'lineId') AS fid, l -> 'comparative' ->> 'asReportedMinor' AS rep
              FROM jsonb_array_elements(v_comp -> 'lines') l WHERE jsonb_typeof(l -> 'comparative') = 'object') c
      FULL JOIN (SELECT replace(x ->> 'factId', 'fact:current:', 'fact:comparative:') AS fid, x #>> '{value,minorUnits,__bigint__}' AS issued
                   FROM jsonb_array_elements(v_prior.report_document -> 'facts') x
                  WHERE x ->> 'factId' LIKE 'fact:current:%' AND x ->> 'factId' NOT LIKE 'fact:current:account:%' AND x ->> 'factId' NOT LIKE 'fact:current:total:%') f
        ON f.fid = c.fid
     WHERE c.rep IS DISTINCT FROM f.issued) s;
  SELECT coalesce(array_agg('COMPARATIVE_NOT_AS_ISSUED:' || (d ->> 'factId') || ':' || coalesce(d ->> 'differenceMinor', CASE WHEN d ->> 'issuedMinor' IS NULL THEN 'not_issued' ELSE 'not_presented' END) ORDER BY d ->> 'factId'), '{}')
    INTO v_blockers FROM jsonb_array_elements(v_diffs) d;
  v_body := jsonb_build_object('contract', 'fs-prior-final-reconciliation/1', 'periodYear', p_period_year,
    'priorFinal', jsonb_build_object('reportId', v_prior.report_id, 'reportVersion', v_prior.report_version, 'documentSha256', v_prior.doc_sha, 'issuedAt', v_prior.created_at),
    'comparativeCertificationId', v_comp -> 'comparative' ->> 'certificationId', 'differences', v_diffs, 'blockers', to_jsonb(v_blockers));
  RETURN jsonb_build_object('state', CASE WHEN v_blockers = '{}' THEN 'reconciled' ELSE 'differences' END) || v_body
         || jsonb_build_object('reconciliationSha256', encode(sha256(convert_to(v_body::text, 'UTF8')), 'hex'));
END;
$$;

-- ── 6. Reporting dependencies v3: the evidence statements and the prior-FINAL reconciliation are bound ───────────────
CREATE OR REPLACE FUNCTION public.fs_reporting_dependencies(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_comp jsonb;
  v_notes jsonb;
  v_cmp jsonb;
  v_ev jsonb;
  v_pf jsonb;
  v_figures jsonb;
  v_body jsonb;
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  v_comp := public.fs_statement_composition(p_company_id, p_period_year);
  IF v_comp ->> 'state' IS DISTINCT FROM 'composed' THEN RETURN jsonb_build_object('state', coalesce(v_comp ->> 'state', 'unavailable'), 'reason', v_comp ->> 'reason'); END IF;
  v_notes := public.fs_notes_status(p_company_id, p_period_year);
  v_cmp := public.fs_comparatives_status(p_company_id, p_period_year);
  v_ev := public.fs_evidence_statements(p_company_id, p_period_year);
  v_pf := public.fs_prior_final_reconciliation(p_company_id, p_period_year);
  -- Every composed figure under its fixed fact identity: lines per period, and the totals of every complete period.
  SELECT coalesce(jsonb_agg(x ORDER BY x ->> 'factId'), '[]'::jsonb) INTO v_figures FROM (
    SELECT jsonb_build_object('factId', 'fact:' || p.period || ':' || (l ->> 'section') || ':' || (l ->> 'lineId'), 'amountMinor', l -> p.period ->> 'amountMinor') AS x
      FROM jsonb_array_elements(v_comp -> 'lines') l CROSS JOIN (VALUES ('current'), ('comparative')) p(period)
     WHERE jsonb_typeof(l -> p.period) = 'object'
    UNION ALL
    -- Each presented account of each line, from the composition's lineage (an account appears once per period), and each
    -- approved restatement delta of the comparative.
    SELECT jsonb_build_object('factId', CASE WHEN x ->> 'kind' = 'restatement'
                                              THEN 'fact:comparative:restatement:' || (x ->> 'restatementId') || ':' || (l ->> 'section') || ':' || (l ->> 'lineId')
                                              ELSE 'fact:' || (x ->> 'period') || ':account:' || (x ->> 'accountKey') END,
                              'amountMinor', x ->> 'amountMinor')
      FROM jsonb_array_elements(v_comp -> 'lines') l CROSS JOIN LATERAL jsonb_array_elements(l -> 'lineage') x
    UNION ALL
    SELECT jsonb_build_object('factId', 'fact:' || t.key || ':total:' || k.key, 'amountMinor', k.value #>> '{}')
      FROM jsonb_each(v_comp -> 'totals') t CROSS JOIN LATERAL jsonb_each(t.value) k
     WHERE t.value ->> 'state' = 'complete' AND k.key LIKE '%Minor'
    UNION ALL
    -- Total comprehensive income of each complete period, when the notes status composed it (5.5(i), 20261022100000).
    SELECT jsonb_build_object('factId', 'fact:' || t.key || ':total:totalComprehensiveIncomeMinor', 'amountMinor', t.value #>> '{}')
      FROM jsonb_array_elements(coalesce(v_notes -> 'requirements', '[]'::jsonb)) q CROSS JOIN LATERAL jsonb_each(q -> 'totalsMinor') t
     WHERE q ->> 'requirementId' = 'smes.sci.5_5_i' AND q ->> 'status' = 'composed'
    UNION ALL
    -- Every figure of the evidence statements: cash flows, changes in equity, the cash perimeter, ledger completeness (20261111100000).
    SELECT f FROM jsonb_array_elements(coalesce(v_ev -> 'figures', '[]'::jsonb)) f) s;
  v_body := jsonb_build_object('contract', 'fs-reporting-dependencies/3', 'periodYear', p_period_year,
    'packId', v_comp -> 'pack' ->> 'packId', 'linesVersion', v_comp -> 'pack' ->> 'linesVersion',
    'requirementsVersion', (SELECT max(r.pack_version) FROM public.fs_pack_requirements r WHERE r.pack_family = 'ifrs-for-smes'),
    'inputSha256', v_comp ->> 'inputSha256', 'compositionSha256', v_comp ->> 'compositionSha256',
    'notesStatusSha256', v_notes ->> 'statusSha256', 'comparativeStatusSha256', v_cmp ->> 'statusSha256',
    'comparativeState', v_cmp -> 'comparative' ->> 'state', 'comparativeSha256', v_cmp -> 'comparative' ->> 'comparativeSha256',
    'evidenceStatementsSha256', v_ev ->> 'statementsSha256', 'evidenceStatements', v_ev -> 'statements', 'evidenceBatches', coalesce(v_ev -> 'evidenceBatches', '[]'::jsonb),
    'priorFinalReconciliation', jsonb_build_object('state', v_pf ->> 'state', 'priorFinal', v_pf -> 'priorFinal', 'reconciliationSha256', v_pf ->> 'reconciliationSha256'),
    'figures', v_figures,
    'blockers', (SELECT coalesce(jsonb_agg(b), '[]'::jsonb) FROM (
                   SELECT jsonb_array_elements_text(v_comp -> 'blockers') b
                   UNION ALL SELECT jsonb_array_elements_text(coalesce(v_notes -> 'blockers', '[]'::jsonb))
                   UNION ALL SELECT jsonb_array_elements_text(coalesce(v_cmp -> 'comparative' -> 'blockers', '[]'::jsonb))
                   UNION ALL SELECT jsonb_array_elements_text(coalesce(v_ev -> 'blockers', '[]'::jsonb))
                   UNION ALL SELECT 'EVIDENCE_STATEMENTS_UNAVAILABLE:' || coalesce(v_ev ->> 'state', 'unknown') WHERE v_ev ->> 'state' IS DISTINCT FROM 'composed'
                   UNION ALL SELECT jsonb_array_elements_text(coalesce(v_pf -> 'blockers', '[]'::jsonb))) bl));
  RETURN jsonb_build_object('state', 'current') || v_body || jsonb_build_object('dependenciesSha256', encode(sha256(convert_to(v_body::text, 'UTF8')), 'hex'));
END;
$$;

-- ── 7. Publication blockers v3 ──────────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_publication_blockers(p_company_id UUID, p_report_id TEXT, p_version INTEGER)
  RETURNS TEXT[]
  LANGUAGE plpgsql
  VOLATILE
  SET search_path = pg_catalog, public
AS $$
DECLARE
  v_report   public.financial_statement_reports;
  v_req      public.financial_statement_framework_requirements;
  v_b        public.financial_evidence_batches;
  v_out      TEXT[] := '{}';
  v_doc      JSONB;
  v_type     TEXT;
  v_cid      TEXT;
  v_id       TEXT;
  v_latest   INTEGER;
  v_n        INTEGER;
  v_comp_any BOOLEAN;
  v_txt      TEXT;
  v_cov      TEXT;
  v_rec      JSONB;
  v_disc     JSONB;
  v_has_budget BOOLEAN;
  v_input    JSONB;
  v_hashes   TEXT[];
  v_deps     JSONB;
  v_bad      TEXT[];
BEGIN
  SELECT * INTO v_report FROM public.financial_statement_reports r
   WHERE r.report_id = p_report_id AND r.report_version = p_version AND r.company_id = p_company_id;
  IF NOT FOUND THEN
    RETURN ARRAY['REPORT_VERSION_NOT_FOUND'];
  END IF;
  v_doc := v_report.report_document;

  SELECT max(r.report_version) INTO v_latest FROM public.financial_statement_reports r WHERE r.report_id = p_report_id;
  IF v_latest <> p_version THEN v_out := array_append(v_out, 'NOT_LATEST_VERSION'); END IF;

  -- [20261111100000] The one supported publication path: an IFRS for SMEs report derived from the authoritative trial
  -- balance. Every other framework or provenance is refused by name. The generic checks below still report what else is
  -- missing, but no such report can ever reach REVIEWED or FINAL through them (and fs_bind_publication refuses it too).
  IF v_report.provenance_origin IS DISTINCT FROM 'TRIAL_BALANCE_DERIVED' OR v_doc #>> '{framework,kind}' IS DISTINCT FROM 'IFRS_FOR_SMES' THEN
    v_out := v_out || ('PUBLICATION_PATH_UNSUPPORTED:' || coalesce(v_doc #>> '{framework,kind}', 'FRAMEWORK_UNKNOWN') || ':' || coalesce(v_report.provenance_origin, 'PROVENANCE_UNKNOWN'));
  END IF;

  SELECT * INTO v_req FROM public.financial_statement_framework_requirements f WHERE f.framework_kind = v_doc #>> '{framework,kind}';
  IF NOT FOUND THEN
    v_out := array_append(v_out, 'FRAMEWORK_UNKNOWN');
  ELSE
    v_comp_any := jsonb_array_length(coalesce(v_doc -> 'comparativePeriods', '[]'::jsonb)) > 0;
    -- [20261017100000] The first-period exception: an approved first-period declaration (approve_certification, evidence
    -- dated within the period) satisfies the comparative requirement; nothing else does (reference-only figures never do).
    IF v_req.comparatives_required AND NOT v_comp_any AND NOT public.fs_first_period_declared(p_company_id, v_report.period_year) THEN
      v_out := array_append(v_out, 'COMPARATIVE_PERIOD_MISSING');
    END IF;

    FOREACH v_type IN ARRAY v_req.required_statement_types LOOP
      IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == $t)', jsonb_build_object('t', v_type)) THEN
        v_out := v_out || ('MISSING_STATEMENT:' || v_type);
      ELSIF v_req.comparatives_required AND v_comp_any THEN
        FOR v_cid IN SELECT jsonb_array_elements(v_doc -> 'comparativePeriods') ->> 'periodId' LOOP
          IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == $t).sections[*].lines[*].factBindings[*] ? (@.periodId == $c)',
                                   jsonb_build_object('t', v_type, 'c', v_cid)) THEN
            v_out := v_out || ('COMPARATIVE_FIGURES_MISSING:' || v_type || ':' || v_cid);
          END IF;
        END LOOP;
      END IF;
    END LOOP;

    FOREACH v_type IN ARRAY v_req.required_evidence_types LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.financial_evidence_batches b
         WHERE b.company_id = p_company_id AND b.evidence_batch_id = ANY (v_report.evidence_batch_ids) AND b.evidence_type = v_type
      ) THEN
        v_out := v_out || ('REQUIRED_EVIDENCE_MISSING:' || v_type);
      END IF;
    END LOOP;
  END IF;

  FOREACH v_id IN ARRAY v_report.evidence_batch_ids LOOP
    SELECT * INTO v_b FROM public.financial_evidence_batches b WHERE b.evidence_batch_id = v_id AND b.company_id = p_company_id;
    IF NOT FOUND THEN
      v_out := v_out || ('EVIDENCE_MISSING:' || v_id);
    ELSE
      IF v_b.validation_status NOT IN ('VALID', 'VALID_WITH_WARNINGS') THEN v_out := v_out || ('EVIDENCE_NOT_VALID:' || v_id); END IF;
      IF EXISTS (SELECT 1 FROM public.financial_evidence_batches n
                  WHERE n.company_id = v_b.company_id AND n.reporting_period_id = v_b.reporting_period_id AND n.evidence_type = v_b.evidence_type
                    AND n.period_role = v_b.period_role AND n.series_key = v_b.series_key AND n.version > v_b.version) THEN
        v_out := v_out || ('EVIDENCE_SUPERSEDED:' || v_id);
      END IF;
    END IF;
  END LOOP;

  IF v_req.framework_kind IS NOT NULL THEN
    -- Cash-flow authority: a ledger-derived closing figure AND proof that the ledger is complete account by account.
    IF 'STATEMENT_OF_CASH_FLOWS' = ANY (v_req.required_statement_types) THEN
      IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == "STATEMENT_OF_CASH_FLOWS").sections[*].lines[*] ? (@.lineId == "line:cf:closing")') THEN
        v_out := array_append(v_out, 'CASHFLOW_CLOSING_CASH_MISSING');
      END IF;
      IF NOT jsonb_path_exists(v_doc, '$.notes[*] ? (@.noteId == "note:cash-ledger-authority")') THEN
        v_out := array_append(v_out, 'CASHFLOW_LEDGER_AUTHORITY_MISSING');
      ELSIF NOT jsonb_path_exists(v_doc, '$.notes[*] ? (@.noteId == "note:cash-ledger-authority").monetaryFactIds[*] ? (@ starts with "fact:cashroll:ledger:")') THEN
        v_out := array_append(v_out, 'CASHFLOW_LEDGER_AUTHORITY_UNRESOLVED');
      END IF;
    END IF;

    -- Reviewed mappings: the trial balance must have been prepared with every account reviewed and unambiguous.
    IF v_req.requires_mapping_review THEN
      SELECT d ->> 'text' INTO v_cov FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' = 'mapping:coverage' LIMIT 1;
      IF v_cov IS NULL THEN
        v_out := array_append(v_out, 'MAPPING_REVIEW_UNRECORDED');
      ELSIF v_cov !~ '^total=[1-9][0-9]*;unmapped=0;ambiguous=0$' THEN
        v_out := v_out || ('MAPPING_UNREVIEWED:' || left(v_cov, 60));
      END IF;
    END IF;

    -- Disclosure checklist: every framework disclosure area present and not MISSING.
    FOREACH v_id IN ARRAY v_req.disclosure_area_ids LOOP
      SELECT d ->> 'text' INTO v_txt FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' = 'checklist:' || v_id LIMIT 1;
      IF v_txt IS NULL THEN
        v_out := v_out || ('DISCLOSURE_CHECKLIST_ABSENT:' || v_id);
      ELSIF v_txt LIKE 'MISSING:%' THEN
        v_out := v_out || ('DISCLOSURE_CHECKLIST_INCOMPLETE:' || v_id);
      END IF;
    END LOOP;

    -- Budget completeness, wherever a budget is part of this report.
    v_has_budget := EXISTS (SELECT 1 FROM public.financial_evidence_batches b WHERE b.company_id = p_company_id AND b.evidence_batch_id = ANY (v_report.evidence_batch_ids) AND b.evidence_type = 'BUDGET');
    IF jsonb_path_exists(v_doc, '$.textualDisclosures[*] ? (@.disclosureId == "budget:gap")') THEN
      v_out := array_append(v_out, 'BUDGET_COMPARISON_GAP');
    ELSIF v_has_budget AND NOT jsonb_path_exists(v_doc, '$.textualDisclosures[*] ? (@.disclosureId starts with "budget:line:")') THEN
      v_out := array_append(v_out, 'BUDGET_COMPARISON_MISSING');
    END IF;
    FOR v_disc IN SELECT d FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' LIKE 'budget:line:%' ORDER BY d ->> 'disclosureId' LOOP
      v_rec := public.fs_try_jsonb(v_disc ->> 'text');
      IF v_rec IS NULL OR jsonb_typeof(v_rec) <> 'object' THEN
        v_out := v_out || ('BUDGET_LINE_UNREADABLE:' || (v_disc ->> 'disclosureId'));
      ELSE
        IF coalesce(v_rec ->> 'matched', 'false') <> 'true' THEN v_out := v_out || ('BUDGET_LINE_UNMATCHED:' || coalesce(v_rec ->> 'lineKey', '?')); END IF;
        IF v_rec ->> 'required' = 'true' AND coalesce(btrim(v_rec ->> 'explanation'), '') = '' THEN v_out := v_out || ('BUDGET_EXPLANATION_MISSING:' || coalesce(v_rec ->> 'lineKey', '?')); END IF;
      END IF;
    END LOOP;
  END IF;

  -- [20261017100000] A trial-balance report is final only on the CURRENT authoritative reporting input and a finished Close
  -- Review: its trial-balance facts must all come from one input identity equal to fs_reporting_input's now (else stale);
  -- the findings of that authority must have been checked with no unresolved blocking finding; no adjustment may be
  -- awaiting a decision, and no approved adjustment may be awaiting a revalidation decision after a re-check.
  IF v_report.provenance_origin = 'TRIAL_BALANCE_DERIVED' THEN
    v_input := public.fs_reporting_input(p_company_id, v_report.period_year);
    SELECT array_agg(DISTINCT s) INTO v_hashes
      FROM jsonb_path_query(v_doc, '$.facts[*].provenance.source ? (@.artifactKind == "TRIAL_BALANCE").sourceHash') h(s0), LATERAL (SELECT h.s0 #>> '{}' AS s) x;
    IF v_input ->> 'state' IS DISTINCT FROM 'current' THEN
      v_out := v_out || ('REPORTING_INPUT_NOT_AUTHORITATIVE:' || coalesce(v_input ->> 'state', 'unknown'));
    ELSIF v_hashes IS NULL OR array_length(v_hashes, 1) <> 1 OR v_hashes[1] IS DISTINCT FROM v_input ->> 'inputSha256' THEN
      v_out := array_append(v_out, 'REPORTING_INPUT_STALE');
    END IF;
    IF v_input ->> 'state' = 'current' THEN
      IF v_input #>> '{findings,state}' IS DISTINCT FROM 'current' THEN
        v_out := array_append(v_out, 'CLOSE_REVIEW_FINDINGS_NOT_CHECKED');
      ELSIF coalesce((v_input #>> '{findings,unresolvedBlocking}')::integer, 0) > 0 THEN
        v_out := v_out || ('CLOSE_REVIEW_BLOCKING_FINDINGS:' || (v_input #>> '{findings,unresolvedBlocking}'));
      END IF;
      SELECT count(*) INTO v_n FROM public.close_review_adjustments a
       WHERE a.company_id = p_company_id AND a.period_year = v_report.period_year
         AND a.certification_id = (v_input #>> '{current,certificationId}')::uuid AND public._cr_adjustment_status(a.id) = 'proposed';
      IF v_n > 0 THEN v_out := v_out || ('CLOSE_REVIEW_ADJUSTMENTS_UNDECIDED:' || v_n); END IF;
      IF coalesce((v_input ->> 'adjustmentsRequiringRevalidation')::integer, 0) > 0 THEN
        v_out := v_out || ('CLOSE_REVIEW_ADJUSTMENTS_REQUIRE_REVALIDATION:' || (v_input ->> 'adjustmentsRequiringRevalidation'));
      END IF;
    END IF;
  END IF;

  -- [20261021100000, 20261111100000] An IFRS for SMEs trial-balance report is bound to its reporting dependencies — the
  -- database's composition, notes status, comparative status and evidence statements — and its four statements must carry
  -- EXACTLY the database's figures under their fixed fact identities; nothing else may be bound there. Every blocker of
  -- those dependencies is a blocker of the report; any later change makes the binding stale.
  IF v_report.provenance_origin = 'TRIAL_BALANCE_DERIVED' AND v_doc #>> '{framework,kind}' = 'IFRS_FOR_SMES' THEN
    v_deps := public.fs_reporting_dependencies(p_company_id, v_report.period_year);
    IF v_deps ->> 'state' IS DISTINCT FROM 'current' THEN
      v_out := v_out || ('REPORTING_DEPENDENCIES_UNAVAILABLE:' || coalesce(v_deps ->> 'state', 'unknown'));
    ELSE
      IF v_doc #>> '{reportingDependencies,dependenciesSha256}' IS NULL THEN
        v_out := array_append(v_out, 'REPORTING_DEPENDENCIES_UNBOUND');
      ELSIF v_doc #>> '{reportingDependencies,dependenciesSha256}' IS DISTINCT FROM v_deps ->> 'dependenciesSha256' THEN
        v_out := array_append(v_out, 'REPORTING_DEPENDENCIES_STALE');
      END IF;
      -- [20261111100000] The edition the document seals must be the one the server resolves for the period.
      IF v_doc #>> '{framework,version}' IS NULL THEN
        v_out := array_append(v_out, 'FRAMEWORK_EDITION_UNRECORDED');
      ELSIF v_doc #>> '{framework,version}' IS DISTINCT FROM v_deps ->> 'packId' THEN
        v_out := v_out || ('FRAMEWORK_EDITION_MISMATCH:' || (v_doc #>> '{framework,version}') || ':' || (v_deps ->> 'packId'));
      END IF;
      -- [20261111100000] Only the 2015 edition's requirement texts are verified; a report composed under the third edition
      -- (a period beginning on or after 2027-01-01, or an early-application election) is refused by name.
      IF v_deps ->> 'packId' IS DISTINCT FROM 'ifrs-for-smes/2015' THEN
        v_out := v_out || ('FRAMEWORK_EDITION_UNSUPPORTED:' || coalesce(v_deps ->> 'packId', 'unknown'));
      END IF;
      v_out := v_out || ARRAY(SELECT jsonb_array_elements_text(v_deps -> 'blockers'));
      -- [20261111100000] Every evidence batch a server figure rests on is bound to this version.
      FOR v_rec IN SELECT b FROM jsonb_array_elements(coalesce(v_deps -> 'evidenceBatches', '[]'::jsonb)) b LOOP
        IF NOT ((v_rec ->> 'batchId') = ANY (v_report.evidence_batch_ids)) THEN
          v_out := v_out || ('EVIDENCE_NOT_BOUND:' || (v_rec ->> 'type') || ':' || (v_rec ->> 'role'));
        END IF;
      END LOOP;
      -- Every composed figure present with exactly its amount ...
      SELECT array_agg(f ->> 'factId' ORDER BY f ->> 'factId') INTO v_bad
        FROM jsonb_array_elements(v_deps -> 'figures') f
       WHERE NOT jsonb_path_exists(v_doc, '$.facts[*] ? (@.factId == $id && @.value.minorUnits.__bigint__ == $m)',
                                   jsonb_build_object('id', f ->> 'factId', 'm', f ->> 'amountMinor'));
      IF v_bad IS NOT NULL THEN v_out := v_out || ('STATEMENT_FIGURE_MISMATCH:' || array_length(v_bad, 1) || ':' || v_bad[1]); END IF;
      -- ... and nothing else bound on the four statements (20261111100000: the statements of changes in equity and cash flows too).
      SELECT array_agg(DISTINCT b ORDER BY b) INTO v_bad
        FROM jsonb_path_query(v_doc, '$.statements[*] ? (@.type == "STATEMENT_OF_FINANCIAL_POSITION" || @.type == "STATEMENT_OF_PROFIT_OR_LOSS" || @.type == "STATEMENT_OF_CHANGES_IN_EQUITY" || @.type == "STATEMENT_OF_CASH_FLOWS").sections[*].lines[*].factBindings[*].factId') q(j),
             LATERAL (SELECT q.j #>> '{}' AS b) x
       WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_deps -> 'figures') f WHERE f ->> 'factId' = x.b);
      IF v_bad IS NOT NULL THEN v_out := v_out || ('STATEMENT_FIGURE_NOT_COMPOSED:' || array_length(v_bad, 1) || ':' || v_bad[1]); END IF;
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.financial_statement_evaluations e WHERE e.report_id = p_report_id AND e.report_version = p_version) THEN
    v_out := array_append(v_out, 'NOT_EVALUATED');
  ELSE
    v_n := public.fs_unresolved_blocking_count(p_report_id, p_version);
    IF v_n > 0 THEN v_out := v_out || ('BLOCKING_FINDINGS:' || v_n); END IF;
    v_n := public.fs_unmet_reconciliation_count(p_report_id, p_version);
    IF v_n > 0 THEN v_out := v_out || ('RECONCILIATION_UNMET:' || v_n); END IF;
  END IF;
  RETURN v_out;
END;
$$;

-- ── 8. The binding trigger v4: unsupported paths refused at the moment of signing ───────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_bind_publication()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_report public.financial_statement_reports;
  v_deps jsonb;
  v_uid uuid := auth.uid();
  v_member public.firm_members;
  v_policy text;
  v_policy_event uuid;
  v_reviewer uuid;
  v_same boolean := NULL;
BEGIN
  IF NEW.state NOT IN ('REVIEWED', 'FINAL') THEN RETURN NEW; END IF;
  SELECT * INTO v_report FROM public.financial_statement_reports r WHERE r.report_id = NEW.report_id AND r.report_version = NEW.report_version;
  -- [20261111100000] Only an IFRS for SMEs report derived from the authoritative trial balance can be signed; every other
  -- framework or provenance is refused here too, so no publication written behind the canonical path can bypass it.
  IF v_report.provenance_origin IS DISTINCT FROM 'TRIAL_BALANCE_DERIVED' OR v_report.report_document #>> '{framework,kind}' IS DISTINCT FROM 'IFRS_FOR_SMES' THEN
    RAISE EXCEPTION 'PUBLICATION_PATH_UNSUPPORTED: only an IFRS for SMEs report derived from the authoritative trial balance can be reviewed or finalised (framework %, provenance %)',
      coalesce(v_report.report_document #>> '{framework,kind}', 'unknown'), coalesce(v_report.provenance_origin, 'unknown') USING ERRCODE = 'PT409';
  END IF;
  v_deps := public.fs_reporting_dependencies(NEW.company_id, v_report.period_year);
  IF v_deps ->> 'state' IS DISTINCT FROM 'current' OR v_report.report_document #>> '{reportingDependencies,dependenciesSha256}' IS DISTINCT FROM v_deps ->> 'dependenciesSha256' THEN
    RAISE EXCEPTION 'BINDING_STALE: the report is not bound to its current reporting dependencies; save a new version' USING ERRCODE = 'PT409';
  END IF;
  -- [20261111100000] The supported edition only (the 2015 edition's verified requirement texts).
  IF v_deps ->> 'packId' IS DISTINCT FROM 'ifrs-for-smes/2015' THEN
    RAISE EXCEPTION 'FRAMEWORK_EDITION_UNSUPPORTED: only a report under the IFRS for SMEs 2015 edition can be reviewed or finalised (this period resolves to %)', coalesce(v_deps ->> 'packId', 'unknown') USING ERRCODE = 'PT409';
  END IF;
  -- The approver is the AUTHENTICATED caller, and the publication's actor must be that caller's own membership of this
  -- company (20261022100000). A publication written without a session, or naming another member, is refused.
  SELECT * INTO v_member FROM public.firm_members m WHERE m.id = NEW.actor_firm_member_id;
  IF v_uid IS NULL OR NOT FOUND OR v_member.user_id IS DISTINCT FROM v_uid OR v_member.company_id IS DISTINCT FROM NEW.company_id THEN
    RAISE EXCEPTION 'APPROVER_NOT_AUTHENTICATED: a sign-off is recorded only for the authenticated member who makes it' USING ERRCODE = '42501';
  END IF;
  -- [20261024100000] The statement sign-off policy in force. FINAL by the person who recorded REVIEWED is permitted only
  -- for the owner under the recorded solo_owner policy; otherwise two different people sign.
  SELECT s.policy, s.event_id INTO v_policy, v_policy_event FROM public._fs_signoff_policy(NEW.company_id) s;
  IF NEW.state = 'FINAL' THEN
    SELECT b.approver_user_id INTO v_reviewer FROM public.fs_publication_bindings b
     WHERE b.report_id = NEW.report_id AND b.report_version = NEW.report_version AND b.state = 'REVIEWED' ORDER BY b.approved_at DESC NULLS LAST LIMIT 1;
    IF v_reviewer IS NULL THEN
      RAISE EXCEPTION 'SIGNOFF_REVIEWER_UNKNOWN: the reviewer of this version is not recorded; save a new version and sign it again' USING ERRCODE = '42501';
    END IF;
    v_same := v_reviewer = v_uid;
    IF v_same AND NOT (v_policy = 'solo_owner' AND v_member.role = 'owner') THEN
      RAISE EXCEPTION 'SIGNOFF_SEPARATE_APPROVERS_REQUIRED: the final approval must be recorded by someone other than the reviewer (the company''s sign-off policy is %)', v_policy
        USING ERRCODE = '42501';
    END IF;
  END IF;
  INSERT INTO public.fs_publication_bindings (publication_id, company_id, report_id, report_version, state, document_sha256, declared_content_hash, dependencies_sha256, dependencies,
                                              approver_user_id, approver_firm_member_id, approver_role, approver_display_name, approved_at,
                                              signoff_policy, signoff_policy_event_id, same_approver)
  VALUES (NEW.id, NEW.company_id, NEW.report_id, NEW.report_version, NEW.state, encode(sha256(convert_to(v_report.report_document::text, 'UTF8')), 'hex'),
          v_report.content_hash, v_deps ->> 'dependenciesSha256', v_deps,
          v_uid, v_member.id, v_member.role,
          -- The name on record at the moment of approval (NULL when none is recorded; never invented).
          (SELECT nullif(btrim(pr.display_name), '') FROM public.profiles pr WHERE pr.user_id = v_uid),
          NEW.created_at,
          v_policy, v_policy_event, v_same);
  RETURN NEW;
END;
$$;

-- ── Access ───────────────────────────────────────────────────────────────────────────────────────────────────────────
REVOKE ALL ON FUNCTION public._fs_slug(text) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public._fs_ev_cell(jsonb, jsonb, text) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public._fs_ev_minor(text, integer) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public._fs_ev_pick(uuid, integer, text, text, text, integer) FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.fs_evidence_statements(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_evidence_statements(uuid, integer) TO authenticated;
REVOKE ALL ON FUNCTION public.fs_prior_final_reconciliation(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_prior_final_reconciliation(uuid, integer) TO authenticated;
REVOKE ALL ON FUNCTION public.fs_bind_publication() FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON FUNCTION public.fs_decide_requirement(uuid, integer, text, text, text, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_decide_requirement(uuid, integer, text, text, text, uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.fs_notes_status(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_notes_status(uuid, integer) TO authenticated;
REVOKE ALL ON FUNCTION public.fs_reporting_dependencies(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_reporting_dependencies(uuid, integer) TO authenticated;
REVOKE ALL ON FUNCTION public.fs_publication_blockers(UUID, TEXT, INTEGER) FROM PUBLIC, anon, authenticated;

DO $postcondition$
BEGIN
  IF (SELECT count(*) FROM public.fs_pack_requirements r WHERE r.pack_family = 'ifrs-for-smes') <> 59
     OR (SELECT max(r.pack_version) FROM public.fs_pack_requirements r WHERE r.pack_family = 'ifrs-for-smes') <> '1.2.0'
     OR position('PUBLICATION_PATH_UNSUPPORTED' IN pg_get_functiondef('public.fs_publication_blockers(uuid, text, integer)'::regprocedure)) = 0
     OR position('PUBLICATION_PATH_UNSUPPORTED' IN pg_get_functiondef('public.fs_bind_publication()'::regprocedure)) = 0
     OR position('FRAMEWORK_EDITION_UNSUPPORTED' IN pg_get_functiondef('public.fs_bind_publication()'::regprocedure)) = 0
     OR to_regprocedure('public.fs_prior_final_reconciliation(uuid, integer)') IS NULL
     OR has_function_privilege('anon', 'public.fs_prior_final_reconciliation(uuid, integer)', 'EXECUTE')
     OR position('SIGNOFF_SEPARATE_APPROVERS_REQUIRED' IN pg_get_functiondef('public.fs_bind_publication()'::regprocedure)) = 0
     OR has_function_privilege('anon', 'public.fs_evidence_statements(uuid, integer)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.fs_publication_blockers(uuid, text, integer)', 'EXECUTE') THEN
    RAISE EXCEPTION 'POSTCONDITION_FAILED: the publication controls are not in their reviewed state' USING ERRCODE = 'P0001';
  END IF;
END;
$postcondition$;
$cfoclose_payload_42edba2be32aff4e$;
  v_bytes   integer;
  v_sha256  text;
BEGIN
  v_bytes  := octet_length(convert_to(c_payload, 'UTF8'));
  v_sha256 := encode(sha256(convert_to(c_payload, 'UTF8')), 'hex');
  IF v_bytes IS DISTINCT FROM c_bytes OR v_sha256 IS DISTINCT FROM c_sha256 THEN
    RAISE EXCEPTION 'RELEASE_PAYLOAD_MISMATCH: % encloses % bytes with SHA-256 %, expected % bytes with SHA-256 %; nothing was changed',
      c_source, v_bytes, v_sha256, c_bytes, c_sha256 USING ERRCODE = '55000';
  END IF;
  EXECUTE c_payload;
END
$cfoclose_release_42edba2be32aff4e$;
